// EComm — standalone scene 3 (Scene3Dashboard). Transparent background, no scene-level
// fade in/out. Content animates in via its own springs; <Background/> + SceneWrap removed.
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  sceneExit,
  ambientDrift,
} from "../motion";

const COLORS = {
  bg: "#161718",
  card: "#1d1e1f",
  border: "#3d3f43",
  text: "#f4f4f5",
  textMuted: "#bfc1c5",
  textSubtle: "#8c93a8",
  orange: "#F86606",
  orangeDeep: "#FF4800",
  orangeTint: "rgba(248,102,6,0.16)",
};

const FONT_MARKETING = "'GT Walsheim', Inter, sans-serif";
const FONT_PRIMARY = "Inter, sans-serif";
const FONT_MONO = "monospace";


const Scene3Dashboard: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const cardIn = springIn(frame, vfps, 4, "LIQUID");
  const tx = interpolate(cardIn, [0, 1], [40, 0]);
  const sc = interpolate(cardIn, [0, 1], [0.94, 1]);

  // Faster X crossing — punchier SNAPPY springs, tighter delays
  const xIn = springIn(frame, vfps, 32, "SNAPPY");
  const xIn2 = springIn(frame, vfps, 38, "SNAPPY");

  const driftY = ambientDrift(frame, 2, 110, "dash-y");

  return (
    <AbsoluteFill>
      {null}
      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: base * 0.08,
        }}
      >
        <div
          style={{
            position: "relative",
            width: width * 0.62,
            background: COLORS.card,
            border: `1px solid ${COLORS.border}`,
            borderRadius: base * 0.018,
            padding: base * 0.035,
            opacity: cardIn,
            transform: `translateY(${tx + driftY}px) scale(${sc})`,
            boxShadow: "0 24px 64px rgba(0,0,0,0.5)",
          }}
        >
          {/* Title */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: base * 0.014,
              marginBottom: base * 0.025,
            }}
          >
            <div
              style={{
                width: base * 0.022,
                height: base * 0.022,
                borderRadius: base * 0.005,
                background: COLORS.orange,
              }}
            />
            <div
              style={{
                width: base * 0.18,
                height: base * 0.014,
                background: "rgba(255,255,255,0.2)",
                borderRadius: 4,
              }}
            />
            <div style={{ flex: 1 }} />
            <div
              style={{
                display: "flex",
                gap: base * 0.008,
              }}
            >
              {[0, 1, 2].map((i) => (
                <div
                  key={i}
                  style={{
                    width: base * 0.04,
                    height: base * 0.018,
                    background: "rgba(255,255,255,0.08)",
                    borderRadius: base * 0.004,
                  }}
                />
              ))}
            </div>
          </div>

          {/* Stats grid */}
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr 1fr 1fr",
              gap: base * 0.012,
              marginBottom: base * 0.025,
            }}
          >
            {[0, 1, 2, 3].map((i) => (
              <div
                key={i}
                style={{
                  background: "rgba(255,255,255,0.04)",
                  borderRadius: base * 0.008,
                  padding: base * 0.014,
                }}
              >
                <div
                  style={{
                    width: "70%",
                    height: base * 0.007,
                    background: "rgba(255,255,255,0.16)",
                    borderRadius: 3,
                    marginBottom: base * 0.008,
                  }}
                />
                <div
                  style={{
                    width: "60%",
                    height: base * 0.018,
                    background: i === 1 ? COLORS.orange : COLORS.text,
                    borderRadius: 3,
                    opacity: 0.9,
                  }}
                />
              </div>
            ))}
          </div>

          {/* Order list */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: base * 0.008,
            }}
          >
            {[0, 1, 2, 3, 4].map((i) => (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: base * 0.012,
                  padding: `${base * 0.008}px ${base * 0.012}px`,
                  background: "rgba(255,255,255,0.03)",
                  borderRadius: base * 0.006,
                }}
              >
                <div
                  style={{
                    width: base * 0.014,
                    height: base * 0.014,
                    borderRadius: "50%",
                    background: COLORS.orange,
                    opacity: 0.7,
                  }}
                />
                <div
                  style={{
                    width: "30%",
                    height: base * 0.008,
                    background: "rgba(255,255,255,0.2)",
                    borderRadius: 3,
                  }}
                />
                <div
                  style={{
                    flex: 1,
                    height: base * 0.008,
                    background: "rgba(255,255,255,0.08)",
                    borderRadius: 3,
                  }}
                />
                <div
                  style={{
                    width: base * 0.05,
                    height: base * 0.008,
                    background: "rgba(255,255,255,0.16)",
                    borderRadius: 3,
                  }}
                />
              </div>
            ))}
          </div>

          {/* Big X overlay — fast slash-in */}
          <svg
            viewBox="0 0 100 100"
            preserveAspectRatio="none"
            style={{
              position: "absolute",
              inset: 0,
              width: "100%",
              height: "100%",
              pointerEvents: "none",
            }}
          >
            <line
              x1={10}
              y1={10}
              x2={90}
              y2={90}
              stroke={COLORS.orangeDeep}
              strokeWidth={2.2}
              strokeLinecap="round"
              strokeDasharray={120}
              strokeDashoffset={interpolate(xIn, [0, 1], [120, 0])}
              style={{
                filter: `drop-shadow(0 0 ${base * 0.01}px ${COLORS.orangeDeep})`,
              }}
            />
            <line
              x1={90}
              y1={10}
              x2={10}
              y2={90}
              stroke={COLORS.orangeDeep}
              strokeWidth={2.2}
              strokeLinecap="round"
              strokeDasharray={120}
              strokeDashoffset={interpolate(xIn2, [0, 1], [120, 0])}
              style={{
                filter: `drop-shadow(0 0 ${base * 0.01}px ${COLORS.orangeDeep})`,
              }}
            />
          </svg>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

